// Typesetter: turns strings into outlined lettering. No imports, so the build can inline it into the
// standalone lunar script. `src` supplies outlines: src.glyph(face, ch) -> { a, d } with the advance `a`
// and path data `d` in font units (y up); src.kern(face, a, b) -> units.
// Each drawing gets its own sheet(). A glyph outline is written once, in sheet.defs(), and placed with
// <use>, so repeated letters cost a few bytes each. Put ${sheet.defs()} last in the SVG, after all text.
// KIT LAW (IDENTITY_DECISIONS.md §3): the output carries outlines only, never font binaries or names.
function makeType(src, upm = 1000) {
  const cache = new Map();
  const glyph = (face, ch) => { const k = face + '\u0000' + ch; let g = cache.get(k);
    if (!g) cache.set(k, g = { ...src.glyph(face, ch), k }); return g; };
  // lay out runs [{t, face, ...}] on one line, in font units; letter-spacing follows every glyph (as CSS does)
  function layout(runs, size, ls) { const u = upm / size; let x = 0, prev = null; const out = [];
    for (const run of runs) for (const ch of [...run.t]) { const g = glyph(run.face, ch);
      if (prev && prev.face === run.face) x += src.kern(run.face, prev.ch, ch);
      out.push({ run, g, x }); x += g.a + ls * u; prev = { face: run.face, ch }; }
    return { glyphs: out, width: x / u }; }
  const measure = (t, { size, face = 'sans400', ls = 0 }) => layout([{ t, face }], size, ls).width;
  const r2 = n => +n.toFixed(2);
  function sheet() { const ids = new Map();
    const id = g => { if (!ids.has(g.k)) ids.set(g.k, { n: 'g' + ids.size.toString(36), d: g.d }); return ids.get(g.k).n; };
    const open = (x, y, size, extra = '') => `<g transform="translate(${r2(x)} ${r2(y)}) scale(${r2(size / upm * 1e4) / 1e4} ${-r2(size / upm * 1e4) / 1e4})"${extra}>`;
    const use = (g, x, extra = '') => g.d ? `<use href="#${id(g)}"${x ? ` x="${Math.round(x)}"` : ''}${extra}` : '';
    // runs: [{t, fill, face}] set on one baseline; each run keeps its own fill
    function runs(list, { x, y, size, face = 'sans400', ls = 0, anchor = 'start', fill }) {
      const L = layout(list.map(r => ({ face, fill, ...r })), size, ls);
      const x0 = anchor === 'middle' ? x - L.width / 2 : anchor === 'end' ? x - L.width : x;
      let out = open(x0, y, size), cur = null;
      for (const g of L.glyphs) { if (!g.g.d) continue;
        if (g.run !== cur) { out += (cur ? '</g>' : '') + `<g fill="${g.run.fill}">`; cur = g.run; }
        out += use(g.g, g.x) + '/>'; }
      return out + (cur ? '</g>' : '') + '</g>'; }
    const text = (t, o) => runs([{ t }], o);
    // typed: one glyph at a time; inner(i) returns child markup (an animation) for character i
    function typed(t, { x, y, size, face = 'sans400', ls = 0, fill }, attrs, inner) { const L = layout([{ t, face }], size, ls);
      return open(x, y, size, ` fill="${fill}"`) + L.glyphs.map((g, i) => g.g.d ? use(g.g, g.x, ' ' + attrs) + '>' + inner(i) + '</use>' : '').join('') + '</g>'; }
    const defs = () => `<defs>${[...ids.values()].map(v => `<path id="${v.n}" d="${v.d}"/>`).join('')}</defs>`;
    return { measure, text, runs, typed, defs }; }
  return { measure, sheet };
}

// The Lunar Calendar. No imports: the build inlines this file into the standalone daily script
// (out/scripts/lunar.mjs). `type` is a typesetter from typeset.mjs; all lettering is drawn as outlines.
const T = { umbra:'#020714', penumbra:'#101B33', corona:'#F3F6FA', coronaDim:'#B9C2D0', bead:'#F0C24B', earth:'#8A94A3', hair:'#1A2338' };
const f = n => +(+n).toFixed(2);
const pal = th => th==='light'
  ? { bg:T.corona, card:'#FFFFFF', ink:T.umbra, dim:'#4A5466', faint:T.earth, line:'#D5DBE5', dark:'#E6EAF1' }
  : { bg:T.umbra,  card:'#060C1B', ink:T.corona, dim:T.coronaDim, faint:T.earth, line:T.hair, dark:'#0E1628' };
const MON = ['JAN','FEB','MAR','APR','MAY','JUN','JUL','AUG','SEP','OCT','NOV','DEC'];
// moon lit from the left (as the mark); k = lit fraction 0..1
const phase = (cx,cy,R,k) => { if(k>=.995) return `<circle cx="${f(cx)}" cy="${f(cy)}" r="${R}"/>`;
  const rx=f(R*Math.abs(1-2*k)); return `<path d="M${f(cx)} ${f(cy-R)}A${R} ${R} 0 0 0 ${f(cx)} ${f(cy+R)}A${rx} ${R} 0 0 ${k<.5?1:0} ${f(cx)} ${f(cy-R)}Z"/>`; };

function lunar(weeks, total, th, type){   // weeks: [[isoDate, count]] oldest→newest, 52 used
  const p=pal(th), s=type.sheet(), W=1280, H=430, w=weeks.slice(-52), max=Math.max(1,...w.map(x=>x[1]));
  const cols=13, rows=4, x0=128, pitch=(W-2*x0)/(cols-1), y0=128, rp=50, R=16;
  let moons='', labels='', lastMo='';
  w.forEach(([d,n],i)=>{ const c=Math.floor(i/rows), r=i%rows, cx=x0+c*pitch, cy=y0+r*rp;
    const k = n>0 ? .14 + .86*Math.sqrt(n/max) : 0, last=i===w.length-1;
    moons += `<g class="m" style="animation-delay:${f(.2+i*.035)}s"><title>Week of ${d}: ${n} contribution${n===1?'':'s'}</title><circle cx="${cx}" cy="${cy}" r="${R}" fill="${p.dark}" stroke="${p.line}" stroke-width="1.2"/>${k?`<g fill="${p.ink}">${phase(cx,cy,R,k)}</g>`:''}${last?`<circle cx="${cx}" cy="${cy+R+9}" r="3" fill="${T.bead}"/>`:''}</g>`;
    if(r===0){ const mo=MON[new Date(w[Math.min(i+2,w.length-1)][0]+'T00:00:00Z').getUTCMonth()]; if(mo!==lastMo) labels += s.text(mo,{x:cx,y:y0+rows*rp-8,size:13,ls:2,anchor:'middle',fill:p.faint}); lastMo=mo; } });
  return `<svg xmlns="http://www.w3.org/2000/svg" width="${W}" height="${H}" viewBox="0 0 ${W} ${H}" role="img" aria-label="Lunar calendar: ${total} contributions in the last year, drawn as moon phases — one moon per week, fuller means busier.">
<style>
.m{opacity:0;animation:m .48s cubic-bezier(.33,.33,.55,1) forwards}@keyframes m{from{opacity:0}to{opacity:1}}
</style>
<rect width="${W}" height="${H}" rx="22" fill="${p.card}" stroke="${p.line}" stroke-width="2"/>
${s.text('THE LUNAR CALENDAR',{x:64,y:64,size:15,ls:3.6,fill:p.faint})}
${s.runs([{t:total.toLocaleString('en-US')+' ',face:'sans500',fill:p.ink},{t:'contributions · last 52 weeks',fill:p.faint}],{x:W-64,y:64,size:17,anchor:'end'})}
${moons}${labels}
${s.text('One moon per week — the fuller the moon, the busier the week. New moons are quiet weeks. Private work is counted, never shown.',{x:64,y:H-40,size:15,fill:p.faint})}
<circle cx="${W-150}" cy="${H-45}" r="3" fill="${T.bead}"/>${s.text('this week',{x:W-140,y:H-40,size:15,fill:p.faint})}
${s.defs()}</svg>`;
}

const type = makeType({
  glyph(face, ch) { const g = OUTLINES[face] && OUTLINES[face].g[ch]; if (!g) throw new Error('No outline for "' + ch + '" in ' + face + '. Rebuild the script.'); return { a: g[0], d: g[1] }; },
  kern(face, a, b) { return OUTLINES[face].k[a + b] || 0; },
});
const login = process.env.LOGIN || 'ZeroMarks';
const q = `query($l:String!){user(login:$l){contributionsCollection{contributionCalendar{totalContributions weeks{firstDay contributionDays{contributionCount}}}}}}`;
let weeks, total;
if (process.env.WEEKS_FILE) {          // offline run from a saved [[isoDate, count]] file, for testing
  weeks = JSON.parse(fs.readFileSync(process.env.WEEKS_FILE, 'utf8')); total = weeks.reduce((a, w) => a + w[1], 0);
} else {
  const r = await fetch('https://api.github.com/graphql', {method:'POST', headers:{Authorization:`bearer ${process.env.GH_TOKEN}`,'Content-Type':'application/json'}, body:JSON.stringify({query:q, variables:{l:login}})});
  const j = await r.json(); if (!j.data) { console.error(JSON.stringify(j)); process.exit(1); }
  const cal = j.data.user.contributionsCollection.contributionCalendar;
  weeks = cal.weeks.map(w => [w.firstDay, w.contributionDays.reduce((a,d)=>a+d.contributionCount,0)]); total = cal.totalContributions;
}
fs.mkdirSync('assets', {recursive:true});
for (const th of ['dark','light']) fs.writeFileSync(`assets/lunar-${th}.svg`, lunar(weeks, total, th, type));
console.log('weeks', weeks.length, 'total', total);
